 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=10000000};static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Static;
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}static object Get(Type a,string n){return a.GetField(n,F).GetValue(null);}static bool Eq(string a,string b){return String.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}
 static string[] Roots(Database db){using(var t=db.TransactionManager.StartTransaction()){var ms=(BlockTableRecord)t.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);return ms.Cast<ObjectId>().Select(id=>{var e=(Entity)t.GetObject(id,OpenMode.ForRead);return e.Handle.ToString()+":"+e.GetRXClass().Name;}).OrderBy(x=>x).ToArray();}}
