 [CommandMethod("HLCADOFFSETDISPATCHCHECKV2",CommandFlags.Session)]public void Run(){Config c=null;var doc=App.DocumentManager.MdiActiveDocument;var ans=doc.Editor.GetString(new PromptStringOptions("\nRead-only offset dispatch check: "){AllowSpaces=true});if(ans.Status!=PromptStatus.OK)return;
 try{c=J.Deserialize<Config>(File.ReadAllText(ans.StringResult.Trim('"')));Need(!File.Exists(c.receipt)&&NativeGeometryReadV1.Hash(c.dispatch)==c.dispatch_sha256&&NativeGeometryReadV1.Hash(c.failure)==c.failure_sha256,"CHECK_INPUT_IDENTITY");var d=J.Deserialize<Dispatch>(File.ReadAllText(c.dispatch));var proc=System.Diagnostics.Process.GetCurrentProcess();Need(proc.Id==d.host.pid&&proc.StartTime.ToUniversalTime().ToFileTimeUtc()==d.host.created&&Eq(proc.MainModule.FileName,d.host.image),"HOST_IDENTITY");Need(d.dll_sha256=="dfe072f2dab51ae329085403f46ef8b3cf6a45225b7c660e8472dfd3fdcd7002"&&NativeGeometryReadV1.Hash(d.dll)==d.dll_sha256,"OFFSET_IMPLEMENTATION_UNKNOWN");
 var failure=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(c.failure));Need((string)failure["status"]=="BOUND_DISPATCH_FAILED"&&(string)failure["stage"]=="send_command"&&(bool)failure["send_attempted"]&&((string)failure["error"]).Contains("80010001"),"EXPECTED_SEND_REJECTION");
 Need(NativeGeometryReadV1.Hash(d.request)==d.request_sha256,"REQUEST_CHANGED");var request=J.Deserialize<Request>(File.ReadAllText(d.request));Need(request.kind=="polyline_offset"&&NativeGeometryReadV1.Hash(request.job_path)==request.job_sha256,"EXPECTED_OFFSET_JOB");var job=J.Deserialize<Job>(File.ReadAllText(request.job_path));Need(Eq(job.input,d.saved_path)&&job.input_sha256==d.source_sha256&&NativeGeometryReadV1.Hash(d.saved_path)==d.source_sha256&&!File.Exists(job.receipt)&&!File.Exists(job.output),"NO_OFFSET_RESULT_EXPECTED");
 var adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,d.loaded_dll)&&NativeGeometryReadV1.Hash(d.loaded_dll)==d.loaded_dll_sha256&&Eq((string)Get(adapter,"dir"),d.session_dir),"ADAPTER_IDENTITY");Need(!(bool)Get(adapter,"busy")&&!(bool)Get(adapter,"blocked")&&!File.Exists(Path.Combine(d.session_dir,"request.json"))&&doc==(Document)Get(adapter,"doc")&&Eq(doc.Name,d.document)&&doc.Database.TransactionManager.NumberOfActiveTransactions==0,"HOST_NOT_IDLE");adapter.GetMethod("CheckLive",F).Invoke(null,new object[]{job.input,job.input_sha256});
 int count;using(doc.LockDocument())using(var saved=new Database(false,true)){saved.ReadDwgFile(d.saved_path,FileOpenMode.OpenForReadAndAllShare,true,null);saved.CloseInput(true);var liveRoots=Roots(doc.Database);Need(liveRoots.SequenceEqual(Roots(saved)),"MODEL_OBJECT_SET_CHANGED_NO_RELEASE");Need(CadValueCompareV1.Json(Source(doc.Database,job),Source(saved,job)),"OFFSET_SOURCES_CHANGED_NO_RELEASE");count=liveRoots.Length;}
 var result=new{status="RECONCILED_OFFSET_DISPATCH_REJECTION",source_sha256=job.input_sha256,request=d.request,request_sha256=d.request_sha256,job_sha256=request.job_sha256,dispatch=c.dispatch,dispatch_sha256=c.dispatch_sha256,preserved_dispatch=c.failure,failure_sha256=c.failure_sha256,failed_module_sha256=d.dll_sha256,read_only=true,replayed=false,offset_committed=false,model_object_set_equal=true,source_polylines_equal=true,model_count=count,output_absent=true,pid=proc.Id,created=d.host.created};using(var f=new FileStream(c.receipt,FileMode.CreateNew))using(var w=new StreamWriter(f))w.Write(J.Serialize(result));
 }catch(System.Exception e){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="OFFSET_DISPATCH_CHECK_FAILED",error=e.ToString()}));}
 }
}